const domElements={root:document.querySelector('[data-gh="root"]'),loading:document.querySelector('[data-gh="loading"]'),jobFilter:document.querySelector('[data-gh="filter"]'),placeHolder:document.querySelector('[data-gh="placeholder"]'),sectionWrapper:document.querySelector('[data-gh="section-wrapper"]')},departmentIds=[],fetchData=e=>fetch(e).then((e=>{if(!e.ok)throw Error(` ${e.status} ${e.statusText}`);return e.json()}));function writeJobs(){const e=departmentIds.map((e=>fetchData(`https://boards-api.greenhouse.io/v1/boards/${ghSlug}/departments/${e}`).then((e=>{let t=document.getElementById(e.id).querySelector('[data-gh="container"]');e.jobs.forEach((e=>{let o=t.querySelector('[data-gh="listing"]').cloneNode(!0);o.id=e.id;let a=o.querySelector('[data-gh="job-title"]');a.innerText=e.title,a.setAttribute("href",e.absolute_url),o.querySelector('[data-gh="job-location"]').innerText=e.location.name,t.appendChild(o)})),t.querySelector('[data-gh="listing"]').remove()})).catch(console.error)));Promise.all(e).finally((()=>{domElements.loading.classList.add("hidden"),domElements.loading.remove(),domElements.placeHolder.remove(),domElements.root.classList.remove("hidden")}))}domElements.jobFilter.onchange=()=>{const e=domElements.jobFilter.value;document.querySelectorAll('[data-gh="section-wrapper"]').forEach((t=>{t.style.display="all"===e||t.id===e?"block":"none"}))},window.addEventListener("DOMContentLoaded",(()=>{domElements.loading.classList.remove("hidden"),fetchData(`https://boards-api.greenhouse.io/v1/boards/${ghSlug}/departments/`).then((e=>{e.departments.forEach((e=>{if(e.jobs.length>0){departmentIds.push(e.id);let t=domElements.sectionWrapper.cloneNode(!0);t.id=e.id,t.querySelector('[data-gh="section-heading"]').innerText=e.name,t.querySelector('[data-gh="container"]').setAttribute("aria-label",e.name),domElements.root.appendChild(t);let o=new Option(e.name,e.id);domElements.jobFilter.add(o)}}))})).catch(console.error).finally(writeJobs)}));